      "sourceQuestions": [
        {
          "id": "R1-revised",
          "question": "When a planner changes a requested camera pose, can an intent-preserving explanation help a filmmaker revise the shot and correctly predict the physical result?",
          "closestPaperIds": [
            "mr-3d-teaming",
            "cinempc",
            "wyfiwyg",
            "reality-proxy"
          ],
          "counterargument": "Ordinary preview and direct manipulation with equal feedback may suffice; other camera interfaces may already address this.",
          "decisiveTest": "Matched planner and correction; compare baseline preview, explicit violated-constraint feedback and shot-intent explanation. Measure framing preservation, revision time, state prediction and unwanted changes.",
          "feasibilityId": "R1-simulation-first",
          "noveltyStatus": "Unverified; targeted forward search needed before selection",
          "whatIsKnown": "Feasible-goal correction, constrained camera control and proxy manipulation already exist.",
          "whatIsNotKnown": "How operators interpret a correction relative to framing intent and negotiate a revision in MR is not resolved by this bounded set.",
          "overlap": "Feasible-goal correction, constrained camera control and proxy manipulation already exist.",
          "feasibility": {
            "id": "R1-simulation-first",
            "questionId": "R1-revised",
            "datasets": "Authored camera/actor/obstacle scenes with scripted conflicting constraints; these are experimental stimuli, not a claimed public benchmark.",
            "models": "Fixed constrained planner and camera model; use known geometry first. No learned model needed to isolate explanation effect.",
            "training": "None required for first causal UI test; perception/training becomes a separate factor.",
            "equipment": "MR headset + workstation; robot/camera rig and calibrated transforms required for physical-transfer claim; access unconfirmed.",
            "timing": "Log sensor timestamp, map age, user event, planner response, command send, acknowledgement and displayed feedback. Report median/tail delays and hardware separately.",
            "hardLimits": "A pose may be geometrically unreachable, blocked or incompatible with framing and dynamics. Explanation cannot make an infeasible shot executable. Stale maps cannot certify collision safety.",
            "goNoGo": "Reject or narrow if identical constraints plus ordinary preview solve the task equally well."
          }
        },
        {
          "id": "R5-revised",
          "question": "How should collaborators distinguish a proposed spatial revision from a committed and physically executed shot state across asynchronous handoffs?",
          "closestPaperIds": [
            "vrgit",
            "realitygit",
            "mr-3d-teaming"
          ],
          "counterargument": "Transaction states and role permissions may solve this without novel XR interaction; prior work already explores negotiated authority.",
          "decisiveTest": "Use conflicting shot edits and delayed controller acknowledgements; compare ordinary history against explicit proposal/commit/execution provenance. Measure reconciliation correctness and authority understanding.",
          "feasibilityId": "R5-state-study",
          "noveltyStatus": "Unverified; requires closest asynchronous robot/CSCW work",
          "whatIsKnown": "Branching 3D content and physical-workspace historical reconstruction exist; SharedVP already supplies role-attributed versions.",
          "whatIsNotKnown": "State/authority confusion at proposal–commit–execution boundaries is a narrower candidate than another history graph.",
          "overlap": "Branching 3D content and physical-workspace historical reconstruction exist; SharedVP already supplies role-attributed versions.",
          "feasibility": {
            "id": "R5-state-study",
            "questionId": "R5-revised",
            "datasets": "Scripted version/command logs and shot revisions; involve film practitioners to validate realistic conflicts.",
            "models": "Existing SharedVP-style state/version events and a deterministic controller emulator.",
            "training": "No generative training required.",
            "equipment": "Two XR clients/network and recording; physical hardware only if claiming executed-state recovery.",
            "timing": "Inject controlled acknowledgement delays and disconnections; record event ordering and user state interpretation.",
            "hardLimits": "Undoing a virtual version does not undo physical motion, moved props or an already recorded shot. Ownership policy cannot be inferred from job title alone.",
            "goNoGo": "Must add evidence beyond SharedVP findings and existing transaction/history approaches."
          }
        },
        {
          "id": "R4-screening",
          "question": "Does a situated alert help an operator recover a camera team without degrading shot continuity or masking stale robot state?",
          "closestPaperIds": [
            "heterogeneous-mr",
            "kennel",
            "mrpilot",
            "spot-on"
          ],
          "counterargument": "Task transfer is not automatically contribution; current supervision papers not deeply read.",
          "decisiveTest": "Complete supervision-paper audit first; then match alerts, autonomy and controller across interfaces before testing recoveries.",
          "feasibilityId": "R4-defer",
          "noveltyStatus": "Reading-gated; not ready to select",
          "whatIsKnown": "Colocated alerts can alter reaction time independently of command efficiency.",
          "whatIsNotKnown": "Shot continuity and stale-state recovery could define a filmmaking-specific task.",
          "overlap": "Colocated alerts can alter reaction time independently of command efficiency.",
          "feasibility": {
            "id": "R4-defer",
            "questionId": "R4-screening",
            "datasets": "Not selected until supervision papers and task-specific failures are audited.",
            "models": "LLM/team planners optional, not a contribution prerequisite.",
            "training": "Unknown until branch chosen.",
            "equipment": "Multi-robot camera rigs, calibration and safety supervision unconfirmed.",
            "timing": "End-to-end team-state freshness more important than headline headset FPS.",
            "hardLimits": "No physical multi-camera validation without suitable rigs; simulated study must remain labeled simulation.",
            "goNoGo": "Defer full system; too many coupled variables before a bounded user problem is established."
          }
        }
      ]
